import{_ as t,o as a,c as o,aj as n}from"./chunks/framework.BwH0p-pt.js";const u=JSON.parse('{"title":"AI Agent (Agentic PIM)","description":"","frontmatter":{},"headers":[],"relativePath":"2.0/ai-agent/index.md","filePath":"2.0/ai-agent/index.md","lastUpdated":1779693222000}'),s={name:"2.0/ai-agent/index.md"};function r(i,e,l,h,c,d){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="ai-agent-agentic-pim" tabindex="-1">AI Agent (Agentic PIM) <a class="header-anchor" href="#ai-agent-agentic-pim" aria-label="Permalink to &quot;AI Agent (Agentic PIM)&quot;">​</a></h1><p>The <strong>AI Agent</strong> — also called <strong>Agentic PIM</strong> — is a conversational assistant built directly into UnoPim. Instead of clicking through menus and forms, you tell the agent in plain language what you want (&quot;create a T-shirt SKU with these attributes,&quot; &quot;find every product missing a description,&quot; &quot;mirror the up-sells from SKU A onto SKU B&quot;), and it carries out the task for you by calling real PIM operations under the hood.</p><h2 id="what-is-the-ai-agent" tabindex="-1">What is the AI Agent? <a class="header-anchor" href="#what-is-the-ai-agent" aria-label="Permalink to &quot;What is the AI Agent?&quot;">​</a></h2><p>The AI Agent is <strong>different from Magic AI&#39;s wand icons</strong>. Here&#39;s the distinction:</p><table tabindex="0"><thead><tr><th></th><th>Magic AI (wand icons)</th><th>AI Agent (Agentic PIM)</th></tr></thead><tbody><tr><td><strong>Where you trigger it</strong></td><td>Click the wand on a specific field</td><td>Chat button at the bottom-right of any page</td></tr><tr><td><strong>Interaction</strong></td><td>One-shot: click, generate, accept</td><td>Conversation: multi-turn, with memory</td></tr><tr><td><strong>Scope</strong></td><td>One field on one entity</td><td>Anything across the catalog — products, categories, attributes, users, roles, channels</td></tr><tr><td><strong>How it acts</strong></td><td>Produces content for the field</td><td>Calls real PIM tools (create, update, search, import, export, delete, bulk-edit, …)</td></tr><tr><td><strong>Output</strong></td><td>Text or an image</td><td>Results of tool calls, streamed back into chat</td></tr></tbody></table><p>In short: <strong>Magic AI writes content. The AI Agent takes actions.</strong></p><h2 id="how-does-the-ai-agent-work" tabindex="-1">How does the AI Agent work? <a class="header-anchor" href="#how-does-the-ai-agent-work" aria-label="Permalink to &quot;How does the AI Agent work?&quot;">​</a></h2><p>Every chat message flows through this loop:</p><ol><li><strong>You send a message</strong> in the AI Agent Chat panel.</li><li><strong>The agent interprets your intent</strong> using the Platform/Model configured under <strong>Magic AI → Settings → Agentic PIM</strong>, plus the active System Prompt personality and any facts it has remembered about you.</li><li><strong>The agent chooses tools to call</strong> from a library of 30+ PIM tools (see the <a href="./ai-agent-chat.html">AI Agent Chat</a> page for the full list). For complex requests it chains several tools together in a plan.</li><li><strong>Each tool runs against real UnoPim data</strong> — but <strong>only within your ACL permissions</strong>. A tool you don&#39;t have permission for silently refuses to execute.</li><li><strong>Destructive or low-confidence changes go to the Approval Queue</strong> (if your Change Approval Mode is set that way) so you can review them before they&#39;re applied.</li><li><strong>The response streams back into the chat</strong> in real time over Server-Sent Events (SSE), so you see progress as the agent thinks and acts.</li></ol><p>Because the agent has real tools and real data, it&#39;s more powerful than a plain LLM chat — but also more consequential. The Approval Queue, token budget, confidence threshold, and ACL checks exist to keep that power under your control.</p><h2 id="key-capabilities" tabindex="-1">Key Capabilities <a class="header-anchor" href="#key-capabilities" aria-label="Permalink to &quot;Key Capabilities&quot;">​</a></h2><h3 id="product-management" tabindex="-1">Product Management <a class="header-anchor" href="#product-management" aria-label="Permalink to &quot;Product Management&quot;">​</a></h3><p>Create, update, search, copy, delete, and bulk-edit products without leaving the chat. The agent handles single-product tweaks and catalog-wide sweeps equally well.</p><h3 id="data-quality-completeness" tabindex="-1">Data Quality &amp; Completeness <a class="header-anchor" href="#data-quality-completeness" aria-label="Permalink to &quot;Data Quality &amp; Completeness&quot;">​</a></h3><p>Ask the agent to scan the catalog for gaps — missing descriptions, thin SEO fields, products under a completeness threshold — and it produces a structured report plus suggested fixes.</p><h3 id="auto-enrichment" tabindex="-1">Auto-Enrichment <a class="header-anchor" href="#auto-enrichment" aria-label="Permalink to &quot;Auto-Enrichment&quot;">​</a></h3><p>Tell the agent to fill in missing descriptions, meta titles, or any other text field, and it generates content that fits your brand voice (via the active System Prompt) and your prompt templates.</p><h3 id="bulk-operations" tabindex="-1">Bulk Operations <a class="header-anchor" href="#bulk-operations" aria-label="Permalink to &quot;Bulk Operations&quot;">​</a></h3><p>Bulk-update attributes, reassign categories, toggle status, or apply transforms (append/prepend/replace) across many SKUs at once — all from one conversational instruction.</p><h3 id="task-planning" tabindex="-1">Task Planning <a class="header-anchor" href="#task-planning" aria-label="Permalink to &quot;Task Planning&quot;">​</a></h3><p>For multi-step work (&quot;clean up the Summer collection: update prices, add a promotional description, and assign the Sale category&quot;), the agent builds a plan, shows you the steps, and executes them in sequence.</p><h3 id="association-management-new-in-v2-0-x" tabindex="-1">Association Management <em>(New in v2.0.x)</em> <a class="header-anchor" href="#association-management-new-in-v2-0-x" aria-label="Permalink to &quot;Association Management *(New in v2.0.x)*&quot;">​</a></h3><p>Add, remove, list, or mirror related products, up-sells, and cross-sells through conversation — no need to open each product edit page.</p><h3 id="catalog-insights" tabindex="-1">Catalog Insights <a class="header-anchor" href="#catalog-insights" aria-label="Permalink to &quot;Catalog Insights&quot;">​</a></h3><p>Ask for counts, stats, recent activity, or the state of channels, users, and roles. The agent returns structured summaries without you having to navigate to each page.</p><h2 id="real-time-streaming-sse" tabindex="-1">Real-Time Streaming (SSE) <a class="header-anchor" href="#real-time-streaming-sse" aria-label="Permalink to &quot;Real-Time Streaming (SSE)&quot;">​</a></h2><p>The AI Agent streams output using <strong>Server-Sent Events</strong>. As the agent decides what to do and calls each tool, you see the reasoning and results appear progressively in the chat — you don&#39;t have to wait for the whole response to finish. This makes long operations feel responsive.</p><h2 id="conversation-persistence" tabindex="-1">Conversation Persistence <a class="header-anchor" href="#conversation-persistence" aria-label="Permalink to &quot;Conversation Persistence&quot;">​</a></h2><p>Chat sessions are <strong>database-backed</strong>. That means:</p><ul><li>Refreshing the page does not clear the conversation.</li><li>Closing and reopening the browser preserves it.</li><li>Within a single session the agent remembers what you&#39;ve already discussed, so you can refer back (&quot;apply that same change to SKU B too&quot;).</li><li>Between sessions, facts you explicitly ask the agent to <strong>remember</strong> (via the internal <code>RememberFact</code> tool) carry forward.</li></ul><p>See the <strong>Sessions</strong> tab in the chat panel to resume, rename, or delete past conversations.</p><h2 id="acl-authorization" tabindex="-1">ACL Authorization <a class="header-anchor" href="#acl-authorization" aria-label="Permalink to &quot;ACL Authorization&quot;">​</a></h2><p>Every one of the 30+ tools respects your <strong>ACL permissions</strong>. If your admin role cannot delete products, the agent cannot delete products on your behalf — the corresponding tool simply does not execute. This means granting AI Agent access does not widen what any user can do; it only changes <em>how</em> they do it.</p><h2 id="rate-limiting" tabindex="-1">Rate Limiting <a class="header-anchor" href="#rate-limiting" aria-label="Permalink to &quot;Rate Limiting&quot;">​</a></h2><p>To keep the system stable and costs predictable, the AI Agent enforces <strong>30 requests per minute per user</strong>. If you exceed the limit, the agent replies with a retry notice and unblocks automatically after the window passes.</p><h2 id="safety-controls" tabindex="-1">Safety Controls <a class="header-anchor" href="#safety-controls" aria-label="Permalink to &quot;Safety Controls&quot;">​</a></h2><p>Three controls keep the agent&#39;s autonomy in check — all configured from <strong>Magic AI → Settings → Agentic PIM</strong>:</p><ul><li><strong>Daily Token Budget</strong> — caps how much the agent can spend in a 24-hour window.</li><li><strong>Max Agent Steps Per Turn</strong> — caps how many tools it can chain for one user message.</li><li><strong>Change Approval Mode</strong> — routes risky or low-confidence changes through the <a href="./approval-queue.html">Approval Queue</a> before they hit your data.</li></ul><p>And one more signal worth knowing: the <strong>Confidence Threshold</strong>. If the agent&#39;s internal confidence score for a proposed change falls below the threshold, the change is held for manual approval regardless of the approval mode.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>The AI Agent is most effective when you provide clear, specific instructions. Instead of &quot;fix my products,&quot; try &quot;update all products in the Electronics category that are missing a meta description.&quot; Specific intent → specific tool calls → faster, cheaper, more accurate results.</p></div><h2 id="where-to-go-next" tabindex="-1">Where to go next <a class="header-anchor" href="#where-to-go-next" aria-label="Permalink to &quot;Where to go next&quot;">​</a></h2><ul><li><strong><a href="./ai-agent-chat.html">AI Agent Chat</a></strong> — How to open, interact with, and manage chat sessions; full list of 30+ tools.</li><li><strong><a href="./approval-queue.html">Approval Queue</a></strong> — How AI-proposed changes are reviewed, approved, or rejected.</li><li><strong><a href="./analytics.html">Analytics</a></strong> — Token usage, cost, and activity dashboards for the agent.</li><li><strong><a href="./../configuration/magic-ai.html">Magic AI Configuration</a></strong> — Platforms, Settings, Prompts, and System Prompts that power the agent.</li></ul>',42)])])}const p=t(s,[["render",r]]);export{u as __pageData,p as default};
